/* @autogenerated */
import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import { BaseExportAction } from 'app/shared/toolkit/action/base-export-action';
import { SnippetRepository } from 'app/features/template/snippet/repository/snippet-repository.service';
import { ExportDefinition } from 'app/shared/toolkit/entity-export/entity-export.model';
import {
  SNIPPET_EXCEL_COLUMNS,
  SNIPPET_EXCEL_SENSITIVE,
} from 'app/features/template/snippet/model/snippet-excel-columns';
import { take, map } from 'rxjs';
import { Snippet } from 'app/features/template/snippet/model/snippet.model';
import { Component, inject } from '@angular/core';

@Component({
  selector: 'snippet-view-export-action',
  standalone: false,
  templateUrl: './snippet-view-export-action.component.html',
})
export class SnippetViewExportActionComponent extends BaseExportAction<Snippet> {
  protected readonly scope = 'template/snippet';
  protected readonly repository = inject(SnippetRepository);
  private readonly tenantRepository = inject(TenantRepository);

  readonly definition: ExportDefinition<Snippet> = {
    name: 'template.snippet',
    scope: this.scope,
    // Las mismas columnas que la importación: el fichero se puede editar y volver a subir
    columns: SNIPPET_EXCEL_COLUMNS,
    sensitive: SNIPPET_EXCEL_SENSITIVE,
    references: {
      tenant: {
        names: (refs) =>
          this.tenantRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.name ?? '')]))),
          ),
      },
    },
    source: {
      acl: () => this.repository.checkAcl(),
      list: (filter) => this.repository.list(filter).pipe(take(1)),
    },
  };
}
